#!/usr/bin/env python3
"""Validation harness for the l2cap_check_enc_key_size boundary fix.

The kernel build system (make/cc driver/.config) is unavailable in this runner,
so this harness extracts the REAL l2cap_check_enc_key_size() body from the
checkout under test, compiles it in isolation with gcc-10 against a minimal
struct hci_conn and the real macro values, and exercises the boundary and
adjacent paths.

It is a logic/behavior check on the patched source line, not a kernel build.
Exit code 0 means every expected path behaved as asserted.
"""
from __future__ import annotations

import re
import subprocess
import sys
import tempfile
from pathlib import Path

GCC = "/usr/bin/gcc-10"
HCI_MIN_ENC_KEY_SIZE = 7
HCI_LM_ENCRYPT = 0x0004

EXTRACT_RE = re.compile(
    r"static\s+bool\s+l2cap_check_enc_key_size\s*\(struct hci_conn \*hcon\)\s*\{.*?\n\}",
    re.S,
)


def extract_function(source: str) -> str:
    match = EXTRACT_RE.search(source)
    if not match:
        raise SystemExit("FAIL: l2cap_check_enc_key_size() not found in source")
    return match.group(0)


def build_program(function_text: str) -> str:
    return f"""
#include <stdio.h>
#include <stdbool.h>

#define HCI_MIN_ENC_KEY_SIZE {HCI_MIN_ENC_KEY_SIZE}
#define HCI_LM_ENCRYPT {HCI_LM_ENCRYPT}

struct hci_conn {{
    unsigned short link_mode;
    unsigned char enc_key_size;
}};

/* ---- begin function extracted verbatim from net/bluetooth/l2cap_core.c ---- */
{function_text}
/* ---- end extracted function ---- */

static int failures = 0;

static void expect(const char *name, bool got, bool want)
{{
    if (got != want) {{
        printf("FAIL %s: got %d want %d\\n", name, got, want);
        failures++;
    }} else {{
        printf("ok   %s\\n", name);
    }}
}}

int main(void)
{{
    struct hci_conn c;

    /* Negative paths: encrypted link below the minimum must be rejected. */
    c.link_mode = HCI_LM_ENCRYPT; c.enc_key_size = 0;
    expect("encrypted key=0 rejected", l2cap_check_enc_key_size(&c), false);
    c.enc_key_size = 1;
    expect("encrypted key=1 rejected", l2cap_check_enc_key_size(&c), false);
    c.enc_key_size = 6;
    expect("encrypted key=6 rejected", l2cap_check_enc_key_size(&c), false);

    /* Boundary path: HCI_MIN_ENC_KEY_SIZE itself must be accepted. */
    c.enc_key_size = HCI_MIN_ENC_KEY_SIZE;
    expect("encrypted key=7 accepted (boundary)", l2cap_check_enc_key_size(&c), true);

    /* Positive paths: larger keys accepted. */
    c.enc_key_size = HCI_MIN_ENC_KEY_SIZE + 1;
    expect("encrypted key=8 accepted", l2cap_check_enc_key_size(&c), true);
    c.enc_key_size = 16;
    expect("encrypted key=16 accepted", l2cap_check_enc_key_size(&c), true);

    /* Unencrypted link has no key-size requirement. */
    c.link_mode = 0; c.enc_key_size = 0;
    expect("unencrypted key=0 accepted", l2cap_check_enc_key_size(&c), true);
    c.enc_key_size = HCI_MIN_ENC_KEY_SIZE;
    expect("unencrypted key=7 accepted", l2cap_check_enc_key_size(&c), true);

    if (failures) {{
        printf("\\n%d assertion(s) failed\\n", failures);
        return 1;
    }}
    printf("\\nall boundary assertions passed\\n");
    return 0;
}}
"""


def main() -> int:
    source_path = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("net/bluetooth/l2cap_core.c")
    source = source_path.read_text(encoding="utf-8", errors="replace")
    function_text = extract_function(source)
    if ">=" not in function_text:
        printf_guard = function_text
        raise SystemExit("FAIL: extracted function does not contain the fixed '>=' comparison\n" + printf_guard)
    program = build_program(function_text)
    with tempfile.TemporaryDirectory(prefix="l2cap-boundary-") as tmp:
        c_file = Path(tmp) / "boundary.c"
        bin_file = Path(tmp) / "boundary"
        c_file.write_text(program, encoding="utf-8")
        compile_result = subprocess.run([GCC, "-O0", "-Wall", str(c_file), "-o", str(bin_file)],
                                        capture_output=True, text=True)
        sys.stdout.write(compile_result.stdout)
        sys.stderr.write(compile_result.stderr)
        if compile_result.returncode != 0:
            print("FAIL: gcc compile failed")
            return 2
        run_result = subprocess.run([str(bin_file)], capture_output=True, text=True)
        sys.stdout.write(run_result.stdout)
        sys.stderr.write(run_result.stderr)
        return run_result.returncode


if __name__ == "__main__":
    raise SystemExit(main())

